/**
 * 数字逻辑检测手布（4 层）：
 *   F.Cu  — LOGIC_H/L 总线、本地短连
 *   In1.Cu — GND 干线
 *   In2.Cu — VCC 干线
 *   B.Cu  — CLK / Q 扇出到排针
 */
function handLayoutLabDigital(doc) {
  doc.tracks = [];
  doc.vias = [];
  doc.zones = [];
  doc.footprints = doc.footprints.filter(f => !!f.schematicCompId);

  // 纠正封装：74HC→DIP14，CD4017→DIP16
  for (const fp of doc.footprints) {
    const want = fp.refDes === 'U7' ? 'FP_DIP16'
      : /^U[1-6]$/.test(fp.refDes) ? 'FP_DIP14' : null;
    if (!want || fp.defId === want) continue;
    const neu = instantiate(want, fp.refDes, fp.value || fp.refDes, fp.position, 0, fp.schematicCompId);
    fp.defId = neu.defId;
    fp.pads = neu.pads;
    for (const pad of fp.pads) { pad.netId = undefined; pad.netName = undefined; }
  }

  const byRef = new Map(doc.footprints.map(f => [f.refDes, f]));
  const setPos = (ref, x, y, rot = 0) => {
    const fp = byRef.get(ref);
    if (!fp) return;
    fp.position = { x, y };
    fp.rotation = rot;
    fp.mirrored = false;
    fp.layer = 'F.Cu';
  };
  const netByName = (name) => doc.nets.find(n => (n.name || '').toUpperCase() === name);
  const gnd = doc.nets.find(n => isGndNet(n.name));
  const vcc = netByName('VCC');
  const logicH = netByName('LOGIC_H');
  const logicL = netByName('LOGIC_L');
  const clk = netByName('CLK');
  const la = [];
  for (let i = 1; i <= 7; i++) la.push(netByName(`LA_CH${i}`));

  const bindPad = (ref, num, net) => {
    const fp = byRef.get(ref);
    const pad = fp?.pads.find(p => p.number === String(num));
    if (!pad || !net) return;
    pad.netId = net.id;
    pad.netName = net.name;
  };

  // 74HC：7=GND 14=VCC；输入 1=H，双门再接 2=L
  for (let i = 1; i <= 6; i++) {
    const ref = `U${i}`;
    bindPad(ref, 7, gnd);
    bindPad(ref, 14, vcc);
    bindPad(ref, 1, logicH);
    if (i !== 3) bindPad(ref, 2, logicL); // U3=74HC04 仅 1 输入
  }
  // CD4017
  bindPad('U7', 8, gnd);
  bindPad('U7', 16, vcc);
  bindPad('U7', 13, clk);
  bindPad('U7', 14, logicL); // EN
  bindPad('U7', 15, logicL); // RST
  const qPads = [3, 2, 4, 7, 10, 1, 5]; // Q0..Q6
  for (let i = 0; i < 7; i++) bindPad('U7', qPads[i], la[i]);

  bindPad('RHI', 1, vcc);
  bindPad('RHI', 2, logicH);
  bindPad('RLO', 1, logicL);
  bindPad('RLO', 2, gnd);

  // 布局
  setPos('RHI', 180, 200, 0);
  setPos('RLO', 180, 420, 0);
  for (let i = 0; i < 6; i++) {
    setPos(`U${i + 1}`, 420 + i * 280, 360, 0);
  }
  setPos('U7', 2100, 360, 0);

  const hdr = instantiate('FP_PINHDR_8', 'J1', '1x8', { x: 2420, y: 420 }, 0);
  const hdrNets = [gnd, vcc, logicH, logicL, clk, la[0], la[1], la[2]];
  for (let i = 0; i < hdr.pads.length; i++) {
    const n = hdrNets[i];
    if (!n) continue;
    hdr.pads[i].netId = n.id;
    hdr.pads[i].netName = n.name;
  }
  doc.footprints.push(hdr);
  byRef.set('J1', hdr);

  const pw = (ref, num) => {
    const fp = byRef.get(ref) || doc.footprints.find(f => f.refDes === ref);
    const pad = fp?.pads.find(p => p.number === String(num));
    return pad ? padWorld(fp, pad) : null;
  };
  const add = (net, a, b, w = 14, layer = 'F.Cu') => {
    if (!net || !a || !b || dist(a, b) < 0.5) return;
    doc.tracks.push({
      id: uid('trk'), layer,
      start: { x: a.x, y: a.y }, end: { x: b.x, y: b.y },
      width: w, netId: net.id, netName: net.name
    });
  };
  const viaLayers = ['F.Cu', 'In1.Cu', 'In2.Cu', 'B.Cu'];
  const addVia = (net, p) => {
    if (!net || !p) return;
    for (const v of doc.vias) {
      if (v.netId === net.id && Math.abs(v.position.x - p.x) < 0.5 &&
        Math.abs(v.position.y - p.y) < 0.5) return;
    }
    doc.vias.push({
      id: uid('via'), position: { x: p.x, y: p.y },
      drill: 12, diameter: 24,
      netId: net.id, netName: net.name,
      layers: [...viaLayers], kind: 'through'
    });
  };
  const L = (net, pts, w = 14, layer = 'F.Cu') => {
    for (let i = 0; i < pts.length - 1; i++) add(net, pts[i], pts[i + 1], w, layer);
  };
  const toPlane = (net, padPt, dx, dy, plane, w = 14) => {
    if (!net || !padPt) return null;
    const e = { x: padPt.x + dx, y: padPt.y + dy };
    add(net, padPt, e, w, 'F.Cu');
    addVia(net, e);
    const tip = {
      x: e.x + (Math.abs(dx) > Math.abs(dy) ? Math.sign(dx || 1) * 40 : 0),
      y: e.y + (Math.abs(dy) >= Math.abs(dx) ? Math.sign(dy || 1) * 40 : 0)
    };
    if (dist(e, tip) > 0.5) add(net, e, tip, w, plane);
    return e;
  };

  // —— In2：VCC ——
  const vccRailY = 40;
  const vccPts = [];
  for (let i = 1; i <= 6; i++) {
    const e = toPlane(vcc, pw(`U${i}`, 14), 40, 0, 'In2.Cu', 14);
    if (e) vccPts.push(e);
  }
  {
    const e = toPlane(vcc, pw('U7', 16), 40, 0, 'In2.Cu', 14);
    if (e) vccPts.push(e);
  }
  {
    const e = toPlane(vcc, pw('RHI', 1), 0, -40, 'In2.Cu', 14);
    if (e) vccPts.push(e);
  }
  if (vcc && vccPts.length) {
    add(vcc, { x: 120, y: vccRailY }, { x: 2500, y: vccRailY }, 20, 'In2.Cu');
    for (const p of vccPts) {
      if (p.y <= 120) add(vcc, p, { x: p.x, y: vccRailY }, 14, 'In2.Cu');
      else {
        // 芯片 VCC 过孔：先到右缘再上顶轨，避开信号廊
        const col = Math.max(p.x + 30, 2300);
        L(vcc, [p, { x: col, y: p.y }, { x: col, y: vccRailY }], 14, 'In2.Cu');
      }
    }
  }

  // —— In1：GND ——
  for (let i = 1; i <= 6; i++) {
    const p = pw(`U${i}`, 7);
    if (p && gnd) {
      addVia(gnd, p);
      add(gnd, p, { x: p.x - 40, y: p.y }, 12, 'In1.Cu');
    }
  }
  {
    const p = pw('U7', 8);
    if (p && gnd) {
      addVia(gnd, p);
      add(gnd, p, { x: p.x - 40, y: p.y }, 12, 'In1.Cu');
    }
  }
  {
    const p = pw('RLO', 2);
    if (p && gnd) {
      addVia(gnd, p);
      add(gnd, p, { x: p.x - 40, y: p.y }, 12, 'In1.Cu');
    }
  }
  if (gnd) {
    add(gnd, { x: 70, y: 160 }, { x: 70, y: 900 }, 18, 'In1.Cu');
    for (const refNum of [['U1', 7], ['U3', 7], ['U5', 7], ['U7', 8], ['RLO', 2]]) {
      const p = pw(refNum[0], refNum[1]);
      if (!p) continue;
      add(gnd, { x: p.x - 40, y: p.y }, { x: 70, y: p.y }, 12, 'In1.Cu');
    }
  }

  // —— F：LOGIC_H 顶廊（对齐 pin1 y）——
  const hPads = [];
  for (let i = 1; i <= 6; i++) {
    const p = pw(`U${i}`, 1);
    if (p) hPads.push(p);
  }
  const rhi2 = pw('RHI', 2);
  if (rhi2) hPads.unshift(rhi2);
  if (logicH && hPads.length >= 2) {
    const yH = hPads[1].y;
    add(logicH, rhi2, { x: rhi2.x, y: yH }, 12, 'F.Cu');
    for (let i = 0; i < hPads.length - 1; i++) {
      const a = hPads[i], b = hPads[i + 1];
      L(logicH, [
        { x: a.x, y: a.y === yH ? a.y : yH },
        { x: b.x, y: yH },
        b
      ], 12, 'F.Cu');
    }
  }

  // —— F/B：LOGIC_L（双门 pin2 + RLO + U7 EN/RST）——
  const lGatePads = [];
  for (const ref of ['U1', 'U2', 'U4', 'U5', 'U6']) {
    const p = pw(ref, 2);
    if (p) lGatePads.push(p);
  }
  const rlo1 = pw('RLO', 1);
  const u7en = pw('U7', 14);
  const u7rst = pw('U7', 15);
  if (logicL && lGatePads.length) {
    const yL = lGatePads[0].y;
    if (rlo1) {
      add(logicL, rlo1, { x: rlo1.x + 40, y: rlo1.y }, 12, 'F.Cu');
      const mid = { x: rlo1.x + 40, y: yL };
      addVia(logicL, { x: rlo1.x + 40, y: rlo1.y });
      L(logicL, [{ x: rlo1.x + 40, y: rlo1.y }, mid], 12, 'B.Cu');
      addVia(logicL, mid);
      add(logicL, mid, lGatePads[0], 12, 'F.Cu');
    }
    for (let i = 0; i < lGatePads.length - 1; i++) {
      add(logicL, lGatePads[i], lGatePads[i + 1], 12, 'F.Cu');
    }
    // 到 U7 EN/RST：B 廊
    const last = lGatePads[lGatePads.length - 1];
    if (u7en && last) {
      const ea = { x: last.x + 40, y: last.y };
      const eb = { x: u7en.x - 40, y: u7en.y };
      add(logicL, last, ea, 12, 'F.Cu'); addVia(logicL, ea);
      L(logicL, [ea, { x: ea.x, y: 700 }, { x: eb.x, y: 700 }, eb], 12, 'B.Cu');
      addVia(logicL, eb); add(logicL, eb, u7en, 12, 'F.Cu');
    }
    if (u7en && u7rst) add(logicL, u7en, u7rst, 12, 'F.Cu');
  }

  // —— 排针 ——
  const jGnd = pw('J1', 1);
  const jVcc = pw('J1', 2);
  const jH = pw('J1', 3);
  const jL = pw('J1', 4);
  const jClk = pw('J1', 5);
  const jQ0 = pw('J1', 6);
  const jQ1 = pw('J1', 7);
  const jQ2 = pw('J1', 8);
  if (gnd && jGnd) {
    addVia(gnd, jGnd);
    add(gnd, jGnd, { x: jGnd.x - 40, y: jGnd.y }, 14, 'In1.Cu');
  }
  if (vcc && jVcc) {
    addVia(vcc, jVcc);
    add(vcc, jVcc, { x: jVcc.x - 40, y: jVcc.y }, 14, 'In2.Cu');
    L(vcc, [{ x: jVcc.x - 40, y: jVcc.y }, { x: jVcc.x - 40, y: vccRailY }], 14, 'In2.Cu');
  }

  // H/L 到排针：短 F + B
  const fanB = (net, src, jPad, runY, colX) => {
    if (!net || !src || !jPad) return;
    const esc = { x: src.x + 40, y: src.y };
    add(net, src, esc, 12, 'F.Cu');
    addVia(net, esc);
    L(net, [esc, { x: esc.x, y: runY }, { x: colX, y: runY }, { x: colX, y: jPad.y }], 12, 'B.Cu');
    addVia(net, { x: colX, y: jPad.y });
    add(net, { x: colX, y: jPad.y }, jPad, 12, 'F.Cu');
  };
  fanB(logicH, pw('U6', 1), jH, 80, 2280);
  fanB(logicL, pw('U6', 2), jL, 120, 2320);

  // CLK / Q0..Q2：从 U7 走 B
  fanB(clk, pw('U7', 13), jClk, 160, 2360);
  fanB(la[0], pw('U7', 3), jQ0, 200, 2400);
  fanB(la[1], pw('U7', 2), jQ1, 900, 2360);
  fanB(la[2], pw('U7', 4), jQ2, 940, 2400);

  // 其余 Q3..Q6：短桩到过孔（可测），不上排针以免拥挤
  for (let i = 3; i < 7; i++) {
    const p = pw('U7', qPads[i]);
    if (p && la[i]) {
      const e = { x: p.x - 40, y: p.y };
      add(la[i], p, e, 12, 'F.Cu');
      addVia(la[i], e);
    }
  }

  const named = [vcc, gnd, logicH, logicL, clk, ...la];
  return {
    trackCount: doc.tracks.length,
    netCount: named.filter(Boolean).length,
    viaCount: doc.vias.length
  };
}
